import{_ as o,c as a,o as r,b0 as d}from"./chunks/framework.C5ev1SXp.js";const p=JSON.parse('{"title":"LV004-什么是单片机","description":null,"frontmatter":{"title":"LV004-什么是单片机","date":"2026-10-16T07:03:18.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/basic/computer-and-mcu/126d62aa68ae37c5ac7df7d9","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-16T07:03:18.892Z","fulluuid":"5ac7df7d93f946049f46e919611166f9","useduuid":"5ac7df7d9"}},"headers":[],"relativePath":"sdoc/basic/computer-and-mcu/126d62aa68ae37c5ac7df7d9.md","filePath":"sdoc/10-基础篇/02-计算机与单片机基础/LV004-什么是单片机.md","lastUpdated":1792035518000}'),e={name:"sdoc/basic/computer-and-mcu/126d62aa68ae37c5ac7df7d9.md"};function n(s,t,l,i,u,c){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="lv004-什么是单片机" tabindex="-1">LV004-什么是单片机 <a class="header-anchor" href="#lv004-什么是单片机" aria-label="Permalink to &quot;LV004-什么是单片机&quot;">​</a></h1><p>上一篇把计算机拆成了五大部件，并看着它们组成一台&quot;以存储器为中心&quot;的自动机器。这一篇回答一个更直接的问题：<strong>单片机到底是什么？</strong> 答案其实就藏在它的全名里——单片微型计算机（Single-Chip Microcomputer）：<strong>把一台计算机的主要部件集成到一颗芯片上</strong>。</p><p>本篇的阅读主线：先看它是怎么从计算机一步步&quot;缩小&quot;出来的（演进史），再给出严格定义和内部构成，然后理清一圈容易混淆的名词（MCU/MPU/SOC/DSP/FPGA），最后看它能干什么、有哪些家族。</p><h2 id="一、-从计算机到单片机" tabindex="-1">一、 从计算机到单片机 <a class="header-anchor" href="#一、-从计算机到单片机" aria-label="Permalink to &quot;一、 从计算机到单片机&quot;">​</a></h2><h3 id="_1-集成度的演进-三步缩小" tabindex="-1">1. 集成度的演进：三步缩小 <a class="header-anchor" href="#_1-集成度的演进-三步缩小" aria-label="Permalink to &quot;1. 集成度的演进：三步缩小&quot;">​</a></h3><p>回顾 <a href="/scm-docs/sdoc/basic/computer-and-mcu/126d62aa68ae1e86fc6cd55b.html">LV001-计算机的基本组成</a>：一台经典计算机由运算器、控制器、存储器、输入设备、输出设备五大部件组成，其中运算器和控制器合成 CPU。在大型计算机时代，这几个部件各自是一块电路板，甚至一排机柜——一间屋子才装得下一台计算机。</p><p>半导体工艺的进步推动了一场持续的&quot;缩小运动&quot;，可以概括为三步：</p><p>（1）<strong>CPU 做进一颗芯片——微处理器（MPU）诞生</strong>。1971 年 Intel 4004 把运算器和控制器集成到一颗芯片上，计算机的&quot;大脑&quot;缩到了指甲盖大小。但 MPU 只是 CPU，要跑起来还得外挂内存、外挂硬盘、外挂各种接口芯片——一块主板才凑齐一台机器，这就是 PC 的形态；</p><p>（2）<strong>CPU + 存储器 + I/O 接口做进一颗芯片——单片机（MCU）诞生</strong>。工程师们发现，如果把 CPU、少量存储器（ROM + RAM）和 I/O 接口电路全部做进同一颗芯片，就能得到一个&quot;通电就能跑程序&quot;的最小计算机。1976 年 Intel 8048（MCS-48 系列）是早期代表，1980 年 Intel 8051 则成了之后四十年的教科书经典；</p><p>（3）<strong>更多功能做进一颗芯片——片上系统（SOC）出现</strong>。工艺再进一步，把 GPU、通信基带、视频编解码甚至 AI 加速器都塞进一颗芯片，就是今天手机里的 SoC。</p><p>&quot;单片机&quot;这个名字里的&quot;单片&quot;，指的就是第（2）步：<strong>单个芯片</strong>。</p><h3 id="_2-单片机的定义" tabindex="-1">2. 单片机的定义 <a class="header-anchor" href="#_2-单片机的定义" aria-label="Permalink to &quot;2. 单片机的定义&quot;">​</a></h3><blockquote><p><strong>单片机（MCU，Microcontroller Unit）是把中央处理器（CPU）、存储器、定时器和多种 I/O 接口集成在一块芯片上的微型计算机。</strong></p></blockquote><p>拆开这个定义的每个短语，都能对应到上一篇的五大部件：</p><ul><li>&quot;中央处理器&quot;——运算器 + 控制器；</li><li>&quot;存储器&quot;——程序存储器 FLASH + 数据存储器 SRAM；</li><li>&quot;定时器和多种 I/O 接口&quot;——输入输出设备，在单片机里以&quot;片上外设&quot;的形式存在。</li></ul><h3 id="_3-芯片内部有什么" tabindex="-1">3. 芯片内部有什么 <a class="header-anchor" href="#_3-芯片内部有什么" aria-label="Permalink to &quot;3. 芯片内部有什么&quot;">​</a></h3><p>拆开一颗 STM32 的封装，里面是一小片硅。这片硅上刻着的主要模块：</p><ul><li>一个 32 位的 <strong>CPU 内核</strong>（如 Cortex-M3）；</li><li>几十到几百 KB 的 <strong>FLASH</strong>（存程序）；</li><li>几到几十 KB 的 <strong>SRAM</strong>（存变量）；</li><li>一大堆<strong>片上外设</strong>：GPIO、UART、定时器、ADC、SPI、I2C、DMA……</li></ul><p>麻雀虽小，五脏俱全：上一篇框图里的每个部件，在这里都有实体。具体的架构细节（总线怎么连、地址怎么分）留到 <a href="/scm-docs/sdoc/basic/computer-and-mcu/126d62aa68b005d840305a2c.html">LV013-单片机的通用架构</a> 展开。</p><h2 id="二、-一堆容易混淆的名词" tabindex="-1">二、 一堆容易混淆的名词 <a class="header-anchor" href="#二、-一堆容易混淆的名词" aria-label="Permalink to &quot;二、 一堆容易混淆的名词&quot;">​</a></h2><p>电子行业里 CPU、MPU、MCU、SOC、DSP、FPGA 这串缩写经常被混用，它们的区别核心在于<strong>集成度</strong>和<strong>设计目标</strong>两个维度。</p><h3 id="_1-cpu-中央处理器" tabindex="-1">1. CPU：中央处理器 <a class="header-anchor" href="#_1-cpu-中央处理器" aria-label="Permalink to &quot;1. CPU：中央处理器&quot;">​</a></h3><p>CPU（Central Processing Unit）就是上一篇定义的&quot;运算器 + 控制器&quot;，是任何计算机必备的&quot;大脑&quot;。它是一个<strong>功能部件</strong>，不是一台完整计算机：单独一颗 CPU 什么都干不了，必须配上存储器和 I/O 才能工作。&quot;电脑里的 i9 处理器&quot;严格说是&quot;包含多核 CPU 的处理器封装&quot;，里面其实还带了内存控制器和缓存。</p><h3 id="_2-mpu-与-mcu-一个字母之差的设计哲学分野" tabindex="-1">2. MPU 与 MCU：一个字母之差的设计哲学分野 <a class="header-anchor" href="#_2-mpu-与-mcu-一个字母之差的设计哲学分野" aria-label="Permalink to &quot;2. MPU 与 MCU：一个字母之差的设计哲学分野&quot;">​</a></h3><p>MPU（Micro Processor Unit，微处理器）和 MCU（MicroController Unit，微控制器）只差一个字母，但代表两种相反的设计取向：</p><table tabindex="0"><thead><tr><th>维度</th><th>MPU（微处理器）</th><th>MCU（微控制器）</th></tr></thead><tbody><tr><td>追求</td><td>计算性能，跑得越快越好</td><td>控制能力，稳定省电便宜</td></tr><tr><td>片内存储</td><td>很少甚至没有，靠外挂大内存</td><td>自带 FLASH + SRAM，单芯片成系统</td></tr><tr><td>典型用法</td><td>外挂 GB 级内存和硬盘，运行操作系统</td><td>单芯片直接控制对象，裸机或 RTOS</td></tr><tr><td>代表</td><td>手机 SoC 里的 CPU 核、嵌入式 Linux 处理器（如 i.MX）</td><td>STM32、8051</td></tr></tbody></table><p>一个帮助记忆的类比：<strong>MPU 是&quot;专业计算器&quot;，MCU 是&quot;瑞士军刀&quot;</strong>。做一台能上网看视频的设备选 MPU；让一台洗衣机的电机按时序正反转，MCU 足矣。</p><h3 id="_3-soc-片上系统" tabindex="-1">3. SOC：片上系统 <a class="header-anchor" href="#_3-soc-片上系统" aria-label="Permalink to &quot;3. SOC：片上系统&quot;">​</a></h3><p>SOC（System on Chip）是集成度的下一站：在 MPU/MCU 基础上把更复杂的功能模块（GPU、Wi-Fi/蓝牙基带、视频编解码、NPU）也集成进一颗芯片，并且强大到通常运行 Linux/Android 这样的大型操作系统。手机主芯片（骁龙、天玑）、树莓派的 BCM2711 都是 SOC。</p><p>SOC 与 MCU 的边界近年确实在模糊（后面 <a href="/scm-docs/sdoc/basic/computer-and-mcu/126d62aa68af2b7b388addac.html">LV010</a> 会展开），但判断口径可以简化为一条：<strong>一颗芯片是否自带足够的存储器和外设、单芯片即可构成控制系统</strong>——是，就是 MCU（或&quot;MCU 型 SOC&quot;）；需要外挂内存才能跑起来的，偏 MPU/SOC。</p><h3 id="_4-dsp-与-fpga-另外两条路线" tabindex="-1">4. DSP 与 FPGA：另外两条路线 <a class="header-anchor" href="#_4-dsp-与-fpga-另外两条路线" aria-label="Permalink to &quot;4. DSP 与 FPGA：另外两条路线&quot;">​</a></h3><ul><li><strong>DSP</strong>（Digital Signal Processor，数字信号处理器）：为&quot;大量乘加运算&quot;专门优化的处理器（一条指令同时完成乘法和加法、硬件循环等），擅长数字滤波、FFT、电机控制算法。TI 的 C2000 系列是电机控制领域的常青树；</li><li><strong>FPGA</strong>（Field Programmable Gate Array，现场可编程门阵列）：严格说不是处理器，而是&quot;可编程的硬件&quot;：用户用硬件描述语言（Verilog/VHDL）定义芯片内部逻辑门的连接，相当于&quot;造一块专用电路&quot;。并行能力极强，用于通信基带、图像采集、协议验证等场景。</li></ul><h3 id="_5-一张总对比表" tabindex="-1">5. 一张总对比表 <a class="header-anchor" href="#_5-一张总对比表" aria-label="Permalink to &quot;5. 一张总对比表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>全称</th><th>本质定位</th><th>典型例子</th></tr></thead><tbody><tr><td>CPU</td><td>Central Processing Unit</td><td>运算器 + 控制器，计算机的大脑</td><td>i9 里的 CPU 核</td></tr><tr><td>MPU</td><td>Micro Processor Unit</td><td>微处理器，性能优先，需外挂存储</td><td>i.MX、RK3588 的核心</td></tr><tr><td><strong>MCU</strong></td><td><strong>MicroController Unit</strong></td><td><strong>微控制器，单芯片成系统，控制优先</strong></td><td><strong>STM32、8051</strong></td></tr><tr><td>SOC</td><td>System on Chip</td><td>片上系统，高度集成，常跑大型 OS</td><td>骁龙、BCM2711</td></tr><tr><td>DSP</td><td>Digital Signal Processor</td><td>信号处理专用处理器</td><td>TI C2000</td></tr><tr><td>FPGA</td><td>Field Programmable Gate Array</td><td>可编程硬件</td><td>Artix-7</td></tr></tbody></table><p>更详细的介绍可以看 <a href="/scm-docs/sdoc/basic/overview/126b08ba0eae364f31526d00.html">01-概述/LV001-ARM体系结构</a>。</p><h2 id="三、-单片机的应用与特点" tabindex="-1">三、 单片机的应用与特点 <a class="header-anchor" href="#三、-单片机的应用与特点" aria-label="Permalink to &quot;三、 单片机的应用与特点&quot;">​</a></h2><h3 id="_1-它藏在你身边的一切设备里" tabindex="-1">1. 它藏在你身边的一切设备里 <a class="header-anchor" href="#_1-它藏在你身边的一切设备里" aria-label="Permalink to &quot;1. 它藏在你身边的一切设备里&quot;">​</a></h3><p>单片机资源少、主频低，但它便宜、省电、体积小、可靠，而且<strong>控制能力强</strong>。你身边到处都是它：</p><ul><li><strong>家用电器</strong>：空调、洗衣机、微波炉、电饭煲、电视遥控器——每一台里有至少一颗；</li><li><strong>消费电子</strong>：电子表、蓝牙耳机、充电宝、玩具；</li><li><strong>汽车电子</strong>：一辆现代汽车里有上百颗 MCU，分别控制发动机喷油、车窗升降、雨刷、安全气囊、胎压监测；</li><li><strong>工业控制</strong>：PLC、变频器、伺服驱动器、机器人关节、传感器变送器；</li><li><strong>物联网</strong>：智能门锁、温湿度监测节点、共享单车智能锁、智能电表水表。</li></ul><h3 id="_2-为什么这些场景都选单片机" tabindex="-1">2. 为什么这些场景都选单片机 <a class="header-anchor" href="#_2-为什么这些场景都选单片机" aria-label="Permalink to &quot;2. 为什么这些场景都选单片机&quot;">​</a></h3><p>把上面这些场景的需求和 MCU 的特性放在一起看，答案自然浮现——这些场景的<strong>共同特点是：不需要强大的算力，但需要实时响应、低功耗、高可靠和低成本</strong>：</p><p>（1）<strong>实时响应</strong>：按键按下几十毫秒内要有反应，电机异常几毫秒内要切断——MCU 的中断响应以微秒计，且时间确定；</p><p>（2）<strong>低功耗</strong>：一节电池要让遥控器工作一两年，MCU 的睡眠模式电流可以低到微安级；</p><p>（3）<strong>高可靠</strong>：家电不能像手机一样每天死机重启，MCU 结构简单、没有复杂操作系统的拖累，配合看门狗可以常年不宕机；</p><p>（4）<strong>低成本</strong>：做家电控制用几块钱的芯片就够，没必要上几十上百块的 MPU。</p><p>这四条恰好就是 MCU 的设计目标——场景需求和芯片设计在这里完全对齐。</p><h2 id="四、-常见的单片机家族" tabindex="-1">四、 常见的单片机家族 <a class="header-anchor" href="#四、-常见的单片机家族" aria-label="Permalink to &quot;四、 常见的单片机家族&quot;">​</a></h2><table tabindex="0"><thead><tr><th>家族</th><th>代表芯片</th><th>特点与地位</th></tr></thead><tbody><tr><td>8051 系</td><td>AT89C51、STC89C52</td><td>1980 年 Intel 推出的经典 8 位架构，结构简单、资料浩如烟海，国内高校教学入门常用；STC 的国产 51 兼容芯片至今生命力顽强</td></tr><tr><td>AVR 系</td><td>ATmega328</td><td>8 位 RISC 架构，Arduino Uno 的主控，被开源生态带火，是很多人&quot;点亮第一颗 LED&quot;的地方</td></tr><tr><td>PIC 系</td><td>PIC16F877A</td><td>Microchip 出品，RISC 架构，抗干扰强，在工业和家电领域存量巨大</td></tr><tr><td>MSP430 系</td><td>MSP430F 系列</td><td>TI 出品，以超低功耗著称，主打电池供电的计量类应用</td></tr><tr><td>STM32 系</td><td>STM32F1/F4/H7</td><td>ST 公司基于 ARM Cortex-M 内核的 32 位 MCU 系列，型号极多、生态完善，是当前国内工业界与教学界的事实主流</td></tr><tr><td>ESP32 系</td><td>ESP32、ESP32-C3</td><td>乐鑫出品，自带 Wi-Fi/蓝牙，性价比极高，物联网明星芯片</td></tr><tr><td>RISC-V 系</td><td>CH32V、GD32V、ESP32-C3</td><td>基于 RISC-V 开源指令集的国产新势力，免授权费，是自主可控方向的重要选项</td></tr></tbody></table><p>一个值得注意的趋势：<strong>指令集从封闭走向开放</strong>。早年各家单片机各有私有指令集（51、AVR、PIC 互不兼容），而今天 ARM Cortex-M 一统 32 位 MCU 江湖，开源的 RISC-V 又正在撕开新的口子。学习时不必纠结&quot;学哪家指令集&quot;——核心概念（寄存器、中断、总线、外设）在所有家族里通用。</p><h2 id="五、-本套文档为什么选-stm32" tabindex="-1">五、 本套文档为什么选 STM32 <a class="header-anchor" href="#五、-本套文档为什么选-stm32" aria-label="Permalink to &quot;五、 本套文档为什么选 STM32&quot;">​</a></h2><p>本套文档选择 <strong>STM32</strong> 作为学习对象，理由有四：</p><p>（1）<strong>内核标准化</strong>：基于 ARM Cortex-M 内核，学到的内核知识（寄存器模型、中断机制、总线架构）直接迁移到 NXP、GD、CH 等其他厂商的芯片；</p><p>（2）<strong>资料丰富</strong>：官方参考手册、应用笔记、社区教程、开源项目数量在所有 MCU 里首屈一指，遇到问题几乎都能搜到答案；</p><p>（3）<strong>生态完善</strong>：开发板便宜易得，Keil/STM32CubeIDE 工具链成熟，HAL 库降低了上手门槛；</p><p>（4）<strong>就业对口</strong>：国内嵌入式岗位的招聘要求中，STM32 出现频率最高。</p><h2 id="六、-小结与下一篇" tabindex="-1">六、 小结与下一篇 <a class="header-anchor" href="#六、-小结与下一篇" aria-label="Permalink to &quot;六、 小结与下一篇&quot;">​</a></h2><ul><li>单片机 = 把 CPU、存储器、I/O 接口集成进<strong>一颗芯片</strong>的微型计算机，是&quot;缩小运动&quot;的第二步产物；</li><li>MCU 与 MPU 的分野在&quot;控制 vs 计算&quot;，与 SOC 的分野在集成度与操作系统；</li><li>单片机为实时、可靠、省电、便宜而生，藏在你身边一切带电的设备里。</li></ul><p>知道了单片机是什么，接下来自然要问：<strong>一套能真正干活的单片机系统由哪些部分组成？硬件和软件各扮演什么角色？</strong> 见 <a href="/scm-docs/sdoc/basic/computer-and-mcu/126d62aa68af11d1e75dc1b7.html">LV007-单片机系统组成</a>。</p><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>',60)])])}const g=o(e,[["render",n]]);export{p as __pageData,g as default};
